from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer using equality-pattern quotient column groups."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to ''."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute common-prefix length using logarithmic C-level slice comparisons."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return exact ideal character-Trie reuse for sorted serialized rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(previous, current)
            for previous, current in zip(ordered, ordered[1:])
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each row using its row-specific source-column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    @staticmethod
    def _factor_codes(cells, column) -> np.ndarray:
        """Encode equal text values in one column as compact integer codes."""
        mapping = {}
        result = np.empty(cells.shape[0], dtype=np.int32)
        next_code = 0
        for row, value in enumerate(cells[:, column]):
            code = mapping.get(value)
            if code is None:
                code = next_code
                mapping[value] = code
                next_code += 1
            result[row] = code
        return result

    def _global_order(self, cells) -> List[int]:
        """Rank columns by length-weighted repeated-value pair mass."""
        n, m = cells.shape
        ranked = []
        for column in range(m):
            counts = {}
            lengths = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                lengths[value] = len(value)
            mass = sum(
                lengths[value] * count * (count - 1)
                for value, count in counts.items()
            )
            ranked.append((mass, column))
        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    @staticmethod
    def _pair_affinity(left, right, left_values, right_values) -> int:
        """Score aligned repeated partitions with text-length and prefix mass."""
        joint = {}
        for a, b in zip(left, right):
            key = (int(a), int(b))
            joint[key] = joint.get(key, 0) + 1

        repeated = 0
        for count in joint.values():
            repeated += count * (count - 1)

        if not repeated:
            return 0

        # Pair repetition is the main quotient signal.  The additional mass
        # favors columns whose actual repeated text can form longer prefixes.
        text_mass = 0
        for value in left_values:
            text_mass += len(value)
        for value in right_values:
            text_mass += len(value)

        return repeated * max(1, text_mass)

    def _quotient_groups(self, cells):
        """Build bounded disjoint groups from strongly aligned value partitions."""
        n, m = cells.shape
        if m <= 1 or n <= 1:
            return [[column] for column in range(m)]

        candidate_count = min(m, 24)
        candidate = list(range(candidate_count))
        codes = [
            self._factor_codes(cells, column)
            for column in candidate
        ]

        edges = []
        for left_index in range(candidate_count):
            for right_index in range(left_index + 1, candidate_count):
                affinity = self._pair_affinity(
                    codes[left_index],
                    codes[right_index],
                    cells[:, candidate[left_index]],
                    cells[:, candidate[right_index]],
                )
                if affinity:
                    edges.append((affinity, left_index, right_index))

        edges.sort(key=lambda item: (-item[0], item[1], item[2]))

        groups = []
        used = set()

        # At most eight pair components are formed; all other columns remain
        # valid singleton components rather than being dropped.
        for _, left_index, right_index in edges:
            if len(groups) >= 8:
                break
            if left_index in used or right_index in used:
                continue
            used.add(left_index)
            used.add(right_index)
            groups.append([candidate[left_index], candidate[right_index]])

        for index, column in enumerate(candidate):
            if index not in used:
                groups.append([column])

        groups.extend([[column] for column in range(candidate_count, m)])

        def component_mass(group):
            """Compute repeated textual mass used to rank quotient components."""
            total = 0
            for column in group:
                counts = {}
                lengths = {}
                for value in cells[:, column]:
                    counts[value] = counts.get(value, 0) + 1
                    lengths[value] = len(value)
                total += sum(
                    lengths[value] * count * (count - 1)
                    for value, count in counts.items()
                )
            return total

        groups.sort(key=lambda group: (-component_mass(group), tuple(group)))

        # Choose each pair orientation by exact repeated concatenated values.
        for group in groups:
            if len(group) != 2:
                continue

            first, second = group
            forward = {}
            reverse = {}

            for row in range(n):
                a = cells[row, first]
                b = cells[row, second]
                forward[a + b] = forward.get(a + b, 0) + 1
                reverse[b + a] = reverse.get(b + a, 0) + 1

            forward_score = sum(
                len(value) * count * (count - 1)
                for value, count in forward.items()
            )
            reverse_score = sum(
                len(value) * count * (count - 1)
                for value, count in reverse.items()
            )

            if reverse_score > forward_score:
                group[:] = [second, first]

        return groups

    def _quotient_orders(self, cells):
        """Construct fixed and row-specific orders from quotient components."""
        n, _ = cells.shape
        groups = self._quotient_groups(cells)

        fixed_order = [
            column
            for group in groups
            for column in group
        ]
        fixed = [fixed_order[:] for _ in range(n)]

        variable = []
        for row in range(n):
            order = []
            for group in groups:
                if len(group) == 2:
                    # Preserve the quotient pair, while allowing the longer
                    # field to lead for row-specific partial-prefix gains.
                    order.extend(sorted(
                        group,
                        key=lambda column: (-len(cells[row, column]), column),
                    ))
                else:
                    order.extend(group)
            variable.append(order)

        return fixed, variable

    def _candidate(self, cells, orders):
        """Serialize and exactly score one candidate, returning sorted row indices."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate global and quotient candidates, then emit a lossless result."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_order = self._global_order(cells)
        quotient, quotient_tail = self._quotient_orders(cells)

        candidates = [
            [global_order[:] for _ in range(n)],
            quotient,
            quotient_tail,
        ]

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))
            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, _, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column]
                for column in source_order
            ]
            column_orders.append([
                df.columns[column]
                for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders


